# Employee portal: new-client form on the start page with the client list on the right, client page + Profiles (pharmacies), Add-pharmacy window, pharmacy page with Users and Billing buttons, one search bar, breadcrumb, owners, licenses, NPI/NCPDP limits, holiday popover, the who-can-manage switches. Run ./reset.sh first.
import json, subprocess, os
from playwright.sync_api import sync_playwright
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'screenshots') + '/'
FAIL = []
def check(name, ok):
    print(("PASS " if ok else "FAIL ") + name)
    if not ok: FAIL.append(name)
def node(arg): return json.loads(subprocess.check_output(["node", "boot.mjs", json.dumps(arg)]).decode().strip().splitlines()[-1])
def measure(pg, sel):
    if not os.environ.get("MEASURE"): return
    print("MEASURE", sel, pg.evaluate("""(sel)=>{const o={};const ps=[...document.querySelectorAll(sel+' .pnl')];let y=1;ps.forEach(n=>{n.style.setProperty('--x',1);n.style.setProperty('--y',y);n.style.setProperty('--w',6);n.style.setProperty('--h',1);y+=400;});return new Promise(r=>setTimeout(()=>{ps.forEach(n=>o[n.dataset.pnl]=[Math.round(n.getBoundingClientRect().height),Math.round(n.getBoundingClientRect().width)]);r(JSON.stringify(o))},300));}""", sel))
node({"makeHost": {"login": "Neo", "name": "Thomas Fisher", "phone": "8175559999", "tempPassword": "hosttemp12a"}})
with sync_playwright() as p:
    b = p.chromium.launch(); pg = b.new_page(viewport={"width": 1500, "height": 1000})
    errs = []; pg.on("pageerror", lambda e: errs.append(str(e)))
    pg.on("dialog", lambda d: d.accept(""))
    pg.goto("http://localhost:8790/host.html"); pg.wait_for_selector("#sUser"); pg.screenshot(path=OUT + "host_signin.png")
    pg.fill("#sUser", "neo"); pg.fill("#sPass", "hosttemp12a"); pg.click("#sGo")
    pg.wait_for_selector("#sNew:visible"); pg.fill("#sNew1", "hostpass999"); pg.fill("#sNew2", "hostpass999"); pg.click("#sNewGo")
    pg.wait_for_selector("#sCode:visible, #side", state="attached")
    if pg.is_visible("#sCode"): pg.fill("#sCodeIn", "123456"); pg.click("#sCodeGo")
    pg.wait_for_selector("#side", state="visible")
    check("no tabs across the top, titled IronLedger employee portal", pg.locator("#hTabs").count() == 0 and "IronLedger employee portal" in pg.inner_text("header.topbar"))
    pg.wait_for_selector("#side [data-qs=NTX1]")
    check("start page: the new-client form is in the middle and the client list is on the right", pg.is_visible("#vNew [data-createclient]") and pg.locator(".cq").bounding_box()["x"] > pg.locator(".cmain").bounding_box()["x"] and "Clients" in pg.inner_text("#side h2"))
    check("start page lists pharmacies not linked to a client yet", "NorTex Pharmacy - Haslet" in pg.inner_text("#side") and "Not linked to a client yet" in pg.inner_text("#side"))
    nc = "#vNew .pcard"
    pg.select_option(nc + " [data-cf=entityType]", "llc"); pg.fill(nc + " [data-cf=legalName]", "IronLedger Compliance LLC"); pg.fill(nc + " [data-cf=ein]", "12-3456789")
    pg.fill(nc + " [data-cf=address]", "100 Main St"); pg.fill(nc + " [data-cf=city]", "Haslet"); pg.select_option(nc + " [data-cf=state]", "TX"); pg.fill(nc + " [data-cf=zip]", "76052")
    pg.select_option(nc + " [data-cownpick]", "@new")
    pg.fill(nc + " [data-cn=name]", "Thomas Fisher"); pg.fill(nc + " [data-cn=login]", "tfisher85"); pg.fill(nc + " [data-cn=phone]", "817-555-0188"); pg.check(nc + " [data-cn=consent]")
    measure(pg, "#vNew")
    pg.screenshot(path=OUT + "host_new_client.png", full_page=True)
    pg.click(nc + " [data-createclient]")
    pg.wait_for_selector("#vClient .pcard")
    check("the client opens: its account in the middle, its Profiles (pharmacies) on the right", "IronLedger Compliance LLC" in pg.inner_text("#vClient") and "Profiles" in pg.inner_text("#side h2") and pg.is_visible("#addP"))
    check("client page opened with a temporary password shown for the new owner", "tfisher85" in pg.inner_text("#passBox") and pg.is_visible("#passBox"))
    check("client page shows the owner", "tfisher85" in pg.inner_text("#vClient [data-pnl=own]"))
    check("client page has no pharmacies or billing panels (those are one level down)", pg.locator("#vClient [data-pnl=pharm], #vClient [data-pnl=bill]").count() == 0)
    check("breadcrumb: Clients > client", "IronLedger Compliance LLC" in pg.inner_text("#crumb"))
    measure(pg, "#vClient")
    pg.screenshot(path=OUT + "host_client_page.png", full_page=True)
    # Add pharmacy: a window, client chosen
    pg.click("#addP"); pg.wait_for_selector("#pmodal:visible")
    mc = "#newStore .pcard"
    check("Add pharmacy opens a window with the client already chosen", pg.eval_on_selector(mc + " [data-sf=clientId]", "e => e.value") != "" and pg.is_disabled(mc + " [data-sf=clientId]"))
    check("licensed entity is in the Pharmacy panel, prefilled from the client", pg.locator(mc + " [data-pnl=id] [data-sf=ein]").count() == 1 and pg.eval_on_selector(mc + " [data-sf=ein]", "e => e.value") == "12-3456789")
    check("licensed entity is no longer in the License panel", pg.locator(mc + " [data-pnl=reg] [data-sf=ein]").count() == 0)
    pg.fill(mc + " [data-newid]", "lag1"); pg.fill(mc + " [data-sf=name]", "Lagniappe Pharmacy"); pg.fill(mc + " [data-sf=address]", "500 Oak St"); pg.fill(mc + " [data-sf=city]", "Denton"); pg.select_option(mc + " [data-sf=state]", "TX"); pg.fill(mc + " [data-sf=zip]", "76201")
    # NPI/NCPDP limits
    pg.eval_on_selector(mc + " [data-sf=npi]", "e => { e.value = '12ab345678901'; e.dispatchEvent(new Event('input', {bubbles: true})); }"); check("NPI: digits only, 10 max", pg.eval_on_selector(mc + " [data-sf=npi]", "e => e.value") == "1234567890")
    check("NPI: bad check digit says so inline", "check digit" in pg.inner_text(mc + " [data-err=npi]"))
    pg.fill(mc + " [data-sf=npi]", "1234567893"); check("NPI: valid shows no error", pg.is_hidden(mc + " [data-err=npi]"))
    pg.fill(mc + " [data-sf=ncpdp]", "12345678"); check("NCPDP: 7 digits max", pg.eval_on_selector(mc + " [data-sf=ncpdp]", "e => e.value") == "1234567")
    check("lookup button next to the NPI box; DEA is a plain field", pg.locator(mc + " .fbtn:has([data-sf=npi]) [data-npilook]").count() == 1 and pg.locator(mc + " [data-sf=dea]").count() == 1 and pg.locator(mc + " .fbtn:has([data-sf=dea])").count() == 0)
    pg.click(mc + " [data-licadd]"); pg.select_option(mc + " [data-licrow] [data-lic=state]", "TX"); pg.fill(mc + " [data-licrow] [data-lic=number]", "TX12345"); pg.fill(mc + " [data-licrow] [data-lic=expires]", "2027-06-30")
    pg.click(mc + " [data-licadd]"); pg.locator(mc + " [data-licrow]").nth(1).locator("[data-lic=state]").select_option("LA"); pg.locator(mc + " [data-licrow]").nth(1).locator("[data-lic=number]").fill("LA777")
    check("four module switches", pg.locator(mc + " [data-sfcal], " + mc + " [data-sfdocs], " + mc + " [data-sfreo], " + mc + " [data-sfrx]").count() == 4 and pg.is_checked(mc + " [data-sfreo]") and pg.is_checked(mc + " [data-sfrx]"))
    check("panel renamed Modules And Save", "modules and save" in pg.inner_text(mc + " [data-pnl=act] h4").lower())
    pg.screenshot(path=OUT + "host_add_pharmacy.png")
    pg.click(mc + " [data-createstore]")
    pg.wait_for_selector("#vPharm .pcard", timeout=15000)
    check("the new pharmacy opens on its own page", pg.is_hidden("#pmodal") and "Lagniappe" in pg.inner_text("#crumb") and "IronLedger Compliance LLC" in pg.inner_text("#crumb"))
    check("licenses saved: two states", pg.locator("#vPharm [data-licrow]").count() == 2)
    check("the pharmacy shows Account, Users and Billing on the right", [b.strip().split("\n")[0] for b in pg.locator("#side .qrow").all_inner_texts()] == ["Account", "Users", "Billing"])
    check("the who-can-manage panel has three switches: owner on, PIC on, client owner off", pg.locator("#vPharm [data-mgr]").count() == 3 and pg.is_checked("#vPharm [data-mgr=mgrOwner]") and pg.is_checked("#vPharm [data-mgr=mgrPic]") and not pg.is_checked("#vPharm [data-mgr=mgrClient]"))
    # owner panel
    check("owner panel: not set yet", "Not set" in pg.inner_text("#vPharm [data-pnl=own]"))
    pg.select_option("#vPharm [data-ownpick]", "tfisher85"); pg.click("#vPharm [data-ownsave]")
    pg.wait_for_selector("#vPharm [data-pnl=own]:has-text('tfisher85')")
    check("owner panel: owner named", "Thomas Fisher" in pg.inner_text("#vPharm [data-pnl=own]"))
    # federal holidays are a visible list (no expanding)
    check("federal holidays are listed in the open: 11 switches visible, no dropdown", pg.locator("#vPharm [data-hol]").count() == 11 and pg.locator("#vPharm .hdlist label.chk").first.is_visible() and pg.locator("#vPharm details.hdrop, #vPharm [data-hsum]").count() == 0)
    check("no DEA check button or status, plain DEA field", pg.locator("#vPharm [data-deaok], #vPharm [data-deastat]").count() == 0 and pg.locator("#vPharm [data-sf=dea]").count() == 1)
    check("the big identity-change block is gone", "Change name, address, license or identifiers" not in pg.inner_text("#vPharm"))
    pg.wait_for_timeout(1500)
    if os.environ.get("MEASURE"):
        print("MEASURE", pg.evaluate("""()=>{const o={};const ps=[...document.querySelectorAll('#vPharm .pnl')];let y=1;ps.forEach(n=>{const w=n.dataset.pnl==='svc'?12:4;n.style.setProperty('--x',1);n.style.setProperty('--y',y);n.style.setProperty('--w',w);n.style.setProperty('--h',1);y+=400;});return new Promise(r=>setTimeout(()=>{ps.forEach(n=>o[n.dataset.pnl]=[Math.round(n.getBoundingClientRect().height),Math.round(n.getBoundingClientRect().width)]);r(JSON.stringify(o))},300));}"""))
    pg.screenshot(path=OUT + "host_pharmacy_page.png", full_page=True)
    # breadcrumb back
    # who may manage people: the switch saves as it is pressed
    pg.click("#vPharm label:has([data-mgr=mgrClient])"); pg.wait_for_selector("#clientMsg:has-text('Saved')")
    check("switching the Client Account Owner on is saved", pg.is_checked("#vPharm [data-mgr=mgrClient]"))
    pg.click("#vPharm label:has([data-mgr=mgrClient])"); pg.wait_for_timeout(600)
    # Users: one pharmacy, a line per person, click for details
    pg.click("#side [data-view=users]"); pg.wait_for_selector("#vUsers .urow")
    pg.locator("#vUsers .urowhead").first.click(); pg.wait_for_selector("#vUsers .udetail"); pg.screenshot(path=OUT + "host_users.png", full_page=True); pg.locator("#vUsers .urowhead").first.click()
    check("Users: the owner of this pharmacy is listed, with a breadcrumb", "tfisher85" in pg.inner_text("#vUsers") and "Users" in pg.inner_text("#crumb"))
    check("Users: no IronLedger employee row", "neo" not in pg.inner_text("#vUsers").lower().split("add a user")[0])
    pg.screenshot(path=OUT + "host_users_list.png", full_page=True)
    pg.click("#vUsers [data-npopen]"); pg.wait_for_selector("#vUsers [data-npmodal] [data-np=name]"); pg.screenshot(path=OUT + "host_add_user_window.png")
    pg.fill("#vUsers [data-np=name]", "Pat Tech"); pg.fill("#vUsers [data-np=login]", "pat.t"); pg.fill("#vUsers [data-np=phone]", "817-555-0199"); pg.check("#vUsers [data-np=consent]")
    pg.click("#vUsers [data-npadd]"); pg.wait_for_selector("#vUsers .urow:has-text('pat.t')")
    check("Users: added person is Pending at the top", "Pending" in pg.inner_text("#vUsers .urow:has-text('pat.t')") and "pat.t" in pg.inner_text("#passBox"))
    pg.wait_for_selector("#vUsers .udetail")
    check("Users: the window closed and the new person is open, ready to toggle privileges", pg.locator("#vUsers [data-npmodal]").count() == 0 and pg.locator("#vUsers .urow.open:has-text('pat.t')").count() == 1)
    check("Users: opening a person shows access, privileges, reset password and delete", pg.locator("#vUsers .udetail [data-ust]").count() == 1 and pg.locator("#vUsers .udetail [data-uperm]").count() == 6 and pg.locator("#vUsers .udetail [data-reset]").count() == 1)
    pg.evaluate("document.querySelector('#vUsers .udetail [data-uperm=remove]').click()")
    pg.wait_for_selector("#vUsers [data-upd]")
    pg.click("#vUsers [data-upd]"); pg.wait_for_selector("#usersMsg:has-text('updated')")
    check("Users: a privilege changed at this pharmacy is saved", not pg.is_checked("#vUsers .udetail [data-uperm=remove]"))
    # Billing: one pharmacy's invoices
    pg.click("#crumb [data-crumb=pharm]"); pg.wait_for_selector("#vPharm .pcard")
    pg.click("#side [data-view=billing]"); pg.wait_for_selector("#vBill .btiles")
    pg.fill("#vBill [data-iv=due]", "2099-01-01"); pg.fill("#vBill [data-iv=amount]", "149"); pg.fill("#vBill [data-iv=description]", "Calendar")
    pg.click("#vBill [data-invadd]"); pg.wait_for_selector("#vBill tr[data-inv]")
    check("Billing: an invoice added to this pharmacy shows as unpaid", "Unpaid" in pg.inner_text("#vBill tbody") and "$149.00" in pg.inner_text("#vBill tbody"))
    pg.click("#vBill [data-invpaid]"); pg.wait_for_selector("#vBill .ust.ok")
    check("Billing: marked paid", "Paid" in pg.inner_text("#vBill tbody"))
    pg.screenshot(path=OUT + "host_billing.png", full_page=True)
    # one search bar: clients, pharmacies, people
    pg.fill("#gFind", "pat.t"); pg.wait_for_selector("#gHits .hit")
    check("search finds a person by username and says where", "LAG1" in pg.inner_text("#gHits"))
    pg.click("#gHits .hit"); pg.wait_for_selector("#vUsers .udetail")
    check("a person hit opens inside that one pharmacy, the person opened", "pat.t" in pg.inner_text("#vUsers .urow.open") and "Lagniappe" in pg.inner_text("#crumb"))
    pg.fill("#gFind", "ironledger comp"); pg.wait_for_selector("#gHits .hit")
    check("search finds a client", "IronLedger Compliance LLC" in pg.inner_text("#gHits"))
    pg.click("#gHits .hit"); pg.wait_for_selector("#vClient .pcard")
    pg.click("#side [data-qs=LAG1]"); pg.wait_for_selector("#vPharm .pcard")
    check("a Profiles line opens the pharmacy page", "Lagniappe" in pg.inner_text("#crumb"))
    pg.click("#crumb [data-crumb=client]"); pg.wait_for_selector("#vClient .pcard")
    check("breadcrumb returns to the client page", "Profiles" in pg.inner_text("#side h2") and "Lagniappe" in pg.inner_text("#side"))
    pg.click("#crumb [data-crumb=home]"); pg.wait_for_selector("#vNew .pcard")
    check("Clients crumb goes back to the start page", "Clients" in pg.inner_text("#side h2") and "IronLedger Compliance LLC" in pg.inner_text("#side"))
    pg.click("#side [data-qs=NTX1]"); pg.wait_for_selector("#vPharm .pcard")
    check("an unlinked pharmacy opens from the start page and can be linked on its page", pg.locator("#vPharm [data-sf=clientId]").count() == 1 and "Haslet" in pg.inner_text("#crumb"))
    check("no script errors", not errs)
    if errs: print(errs)
    b.close()
print("\n" + ("all passed" if not FAIL else "%d failed" % len(FAIL)))
